mapper.select:
SELECT 

		ISNULL(MIN(WO.납기일자), #{searchDtFrom}) AS W_MAX_DATE


		ISNULL(MIN(WO.접수일자), #{searchDtFrom}) AS W_MAX_DATE





		 AND WO.납기일자 >= #{listStartDt} 


		 AND WO.접수일자 >= #{listStartDt}

mapper.sql:

WHERE 1=1 
AND IC.사업장 = #{registBplc}
AND IC.폐기일자 <= CONVERT(VARCHAR,GETDATE(),112)
AND WO.진행유무 = 'N'
AND WO.접수삭제 = 'N'
AND WO.거래처코드 = #{bcncCode}


 AND IC.품목명 LIKE UPPER('%'+ #{searchItemNm} +'%') 


 AND (SELECT RTRIM(CM2.상호) 
				FROM 거래처MASTER CM2 
				WHERE CM2.거래처코드 = WO.착지업체 
				AND CM2.등록사업장 = WO.출고사업장) LIKE UPPER('%'+ #{searchEntrpsNm} +'%') 




		 AND WO.납기일자 >= #{searchDtFrom} 


		 AND WO.납기일자 <= #{searchDtTo} 




		 AND WO.접수일자 >= #{searchDtFrom} 


		 AND WO.접수일자 <= #{searchDtTo}
